import type { SynapseEnhancedHttpClient } from "../utils/http.ts";
import { validateUserId, validateRoomId, validateString } from "../utils/validator.ts";
import type { IFriendRequestV2 } from "../models/friend-requests.types.ts";
import { EnhancedApi } from "../constants/api.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";

export class FriendRequestsApi {
    public constructor(private httpClient: SynapseEnhancedHttpClient) {}

    /**
     * Send a friend request to a user
     * POST /_synapse/enhanced/friend/request
     */
    public async sendFriendRequest(params: { target_user_id: string; message?: string }): Promise<IFriendRequestV2> {
        validateUserId(params.target_user_id);

        if (params.message !== undefined) {
            validateString(params.message, "message", { maxLength: 1000 });
        }

        // Use the friend/request endpoint (singular)
        const endpoint = "/friend/request";

        const response = await this.httpClient.post<{
            status: string;
            data?: IFriendRequestV2;
            error?: string;
        }>(endpoint, params);
        return handleApiResponse(response, "Failed to send friend request");
    }

    /**
     * Get pending friend requests
     * GET /_synapse/enhanced/friend/requests
     */
    public async getFriendRequests(): Promise<IFriendRequestV2[]> {
        const response = await this.httpClient.get<{
            status: string;
            data?: IFriendRequestV2[];
            error?: string;
        }>(EnhancedApi.FRIENDS_REQUESTS);
        return handleApiResponse(response, "Failed to get friend requests")?.requests || [];
    }

    /**
     * Accept a friend request
     * POST /_synapse/enhanced/friend/request/{request_id}/accept
     */
    public async acceptFriendRequest(roomId: string): Promise<{
        room_id: string;
        status: string;
        direct_chats: Record<string, string[]>;
    }> {
        validateRoomId(roomId);

        const response = await this.httpClient.post<{
            status: string;
            data?: {
                room_id: string;
                status: string;
                direct_chats: Record<string, string[]>;
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_REQUEST_ACCEPT.replace("{requestId}", encodeURIComponent(roomId)), {});
        return handleApiResponse(response, "Failed to accept friend request");
    }

    /**
     * Reject (decline) a friend request
     * POST /_synapse/enhanced/friend/request/{request_id}/decline
     */
    public async rejectFriendRequest(roomId: string): Promise<{
        room_id: string;
        status: string;
    }> {
        validateRoomId(roomId);

        const response = await this.httpClient.post<{
            status: string;
            data?: {
                room_id: string;
                status: string;
            };
            error?: string;
        }>(EnhancedApi.FRIENDS_REQUEST_DECLINE.replace("{requestId}", encodeURIComponent(roomId)), {});
        return handleApiResponse(response, "Failed to reject friend request");
    }
}
